    const inc = dc >= 0 ? rows.filter(r => yes(r[dc])) : rows.filter(r => rc < 0 || !String(r[rc] ?? '').trim()), exc = rows.filter(r => !inc.includes(r)), why = {}; exc.forEach(r => { const k = rc >= 0 && String(r[rc] ?? '').trim() ? String(r[rc]).trim().replace(/^\w/, ch => ch.toUpperCase()) : 'Other reasons'; why[k] = (why[k] || 0) + 1; });
