    const head = aoa[hr].map(x => String(x || '')), L = aoa.slice(hr + 1).filter(r => r && r.some(x => x !== null && x !== '')), col = re => head.findIndex(h => re.test(h)), cg = col(/group|arm|allocation|treatment/i), ci = col(/patient|^id$|subject/i), cb = col(/block/i), cs = col(/site|centre|center|stratum/i);
